BEGIN;

-- 刪除測試資料（前 5 題）
DELETE FROM mbti_questions WHERE question_id BETWEEN 1 AND 5;

-- 完整的 40 題測驗問題
INSERT INTO mbti_questions (question_id, text, image_url, dimension_pair, weight, option_a_label, option_a_value, option_b_label, option_b_value, display_order) VALUES
-- E vs I (8 題)
(1, '一週忙到爆，週五晚上你好不容易關上店門／下班回到家。此刻你最想做的是：', 'https://picsum.photos/seed/friday_night_vibe/800/400', 'EI', 2, '打開手機看朋友在哪裡，想問一句：「等等有沒有局？」', 'E', '把手機丟遠一點，泡個熱飲，誰傳訊息都先放著，想安靜一個人待著。', 'I', 1),
(2, '你被朋友臨時拉去一場幾乎全是陌生人的聚會／商務酒會，前 10 分鐘你的狀態通常是：', 'https://picsum.photos/seed/cocktail_party_blur/800/400', 'EI', 1, '先隨便抓一杯飲料，開始在場內繞一圈，找人搭話、認識新朋友。', 'E', '找到角落、牆邊或吧台的位置，先觀察氣氛，看看有沒有看起來聊得來的人。', 'I', 2),
(3, '當你腦中有一個還不成熟的想法時，你比較習慣：', 'https://picsum.photos/seed/lightbulb_sketch/800/400', 'EI', 1, '先說出來跟別人討論，在講的過程中慢慢長出完整的想法。', 'E', '先自己在腦中演練好幾輪，覺得差不多了才找人分享。', 'I', 3),
(4, '手機突然響起，是一通未知來電，你的第一反應是：', 'https://picsum.photos/seed/phone_ringing_dark/800/400', 'EI', 1, '有點好奇是什麼事，反正接起來再說。', 'E', '先皺一下眉，會猶豫要不要接，甚至讓它響完再回撥。', 'I', 4),
(5, '在一場團隊腦力激盪會議中，主持人說：「有想法就直接講！」你會：', 'https://picsum.photos/seed/meeting_room_abstract/800/400', 'EI', 1, '先丟幾個點子出來，不怕還不成熟，覺得先有東西再調整就好。', 'E', '先聽大家的想法，等自己腦中整理成一個比較完整的說法再開口。', 'I', 5),
(6, '對你來說，「朋友」比較像是：', 'https://picsum.photos/seed/friends_laughing/800/400', 'EI', 1, '很多不同圈子的人，平常隨時都有人可以約、可以聊天。', 'E', '少數幾個非常熟的人，真正會說心事的其實只有那幾位。', 'I', 6),
(7, '假設今天你整天都被關在家裡，沒有行程、也不能出門，你覺得：', 'https://picsum.photos/seed/window_rain/800/400', 'EI', 1, '有點快被悶壞了，會想主動開視訊、語音，找人講話。', 'E', '反而覺得難得清靜，終於可以專心做自己的事情，不被打擾。', 'I', 7),
(8, '當你發生一件很值得開心的事（升遷、投標中、作品得獎、暗戀的人回訊息）時，你會：', 'https://picsum.photos/seed/sparkles_joy/800/400', 'EI', 1, '立刻截圖、發限動或打給朋友，想跟一堆人分享這個好消息。', 'E', '先在心裡偷笑，可能只會跟一兩個最親近的人說。', 'I', 8),

-- S vs N (8 題)
(9, '你站在窗邊，看著一片安靜的樹林／山景照片，你腦中首先浮現的是：', 'https://picsum.photos/seed/forest_mist/800/400', 'SN', 2, '風有多冷、樹葉什麼顏色、空氣大概聞起來是潮濕還是乾燥。', 'S', '這裡像一個故事的開頭，讓我聯想到「如果我走進去，會發生什麼事」。', 'N', 9),
(10, '別人跟你描述一件事情時，你會更自然地追問：', 'https://picsum.photos/seed/conversation_cafe/800/400', 'SN', 1, '「所以是幾點？在哪裡？後來具體發生什麼？」', 'S', '「為什麼會這樣？你覺得這背後代表什麼？之後可能會怎麼發展？」', 'N', 10),
(11, '學一個全新的工具或軟體時，你通常的流程是：', 'https://picsum.photos/seed/laptop_hands/800/400', 'SN', 1, '先看教學或操作說明，一步步照做，確認功能再延伸。', 'S', '直接打開開始亂點，邊玩邊猜它的邏輯是什麼。', 'N', 11),
(12, '如果我問你：「你對 5 年後的自己有畫面嗎？」你比較會說：', 'https://picsum.photos/seed/foggy_road/800/400', 'SN', 1, '先把眼前的事做好再說，未來是現在累積出來的。', 'S', '有一堆版本在腦中上演，會想像不同城市、不同工作、不同生活方式。', 'N', 12),
(13, '和朋友去一間主打「創意料理」的新餐廳，菜單上全是沒見過的菜，你會：', 'https://picsum.photos/seed/weird_food/800/400', 'SN', 1, '保守地選看起來最安全、最接近熟悉味道的那幾道。', 'S', '想點名字最怪或最特別的菜，就算踩雷也覺得是一次好玩的經驗。', 'N', 13),
(14, '如果要你寫一篇文章，你會比較有把握的是：', 'https://picsum.photos/seed/typewriter_vintage/800/400', 'SN', 1, '記錄一段真實發生的事情，用細節把畫面講清楚。', 'S', '虛構一個世界，寫一個帶有隱喻、象徵或奇幻元素的故事。', 'N', 14),
